<div class="card"><h1>Listing Templates</h1><?php if(!empty($message)): ?><div class="alert"><?= e($message) ?></div><?php endif; ?><form method="post"><input name="title" placeholder="Title" required><textarea name="description" placeholder="Description" required></textarea><select name="category_id"><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select><select name="condition"><option value="good">Good</option><option value="new">New</option><option value="like_new">Like New</option><option value="fair">Fair</option></select><input type="number" step="0.01" name="starting_price" placeholder="Starting price" required><button>Save Template</button></form></div><div class="card"><table><tr><th>Title</th><th>Category</th><th>Price</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['category_name']) ?></td><td><?= e($r['starting_price']) ?></td><td><a class="btn" href="index.php?page=create_listing&template_id=<?= $r['id'] ?>">Use Template</a></td></tr><?php endforeach; ?></table></div>
